<?php require '../includes/core.php';if(me())go('user/dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=(string)($_POST['password']??'');if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)$error='Informe nome, e-mail válido e senha com pelo menos 8 caracteres.';else{try{$s=db()->prepare("INSERT INTO users (name,email,password,role) VALUES (?,?,?,'user')");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);$newId=(int)db()->lastInsertId();notify_admins('Novo usuário cadastrado',$name.' criou uma conta na plataforma.','admin/users.php');notification_create($newId,'Conta criada com sucesso','Sua conta foi registrada e já está pronta para receber uma assinatura.','plans.php');notify('Conta criada! Faça login para continuar.');go('auth/login.php');}catch(PDOException $e){$error='Este e-mail já está cadastrado ou ocorreu um erro.';}}}layout_start('Cadastro');?><div class="card auth"><span class="kicker">NOVO USUÁRIO</span><h1>Crie sua conta</h1><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><?php fld('name','Nome completo');fld('email','E-mail','email');fld('password','Senha (8 caracteres ou mais)','password');?><button class="btn block">Cadastrar</button></form><p>Já tem conta? <a href="login.php">Entrar</a></p></div><?php layout_end();?>